/**
 *
 * TreeNodes is a flat iterator that renders one row per visible node.
 *
 * [Live Demo](https://www.primereact.org/tree/)
 *
 * @module TreeNodes
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { TreeNodeData } from '@primereact/types/headless/tree';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TreeRootInstance } from './TreeRoot.types';
/**
 * Per-row payload passed to the `Tree.Nodes` render-prop. Each visible node in
 * the tree produces exactly one row.
 */
export interface TreeNodeRow {
    /**
     * The underlying node data.
     */
    node: TreeNodeData;
    /**
     * 1-based depth in the tree (root nodes are level 1).
     */
    level: number;
    /**
     * 1-based position within the parent's children list.
     */
    posInSet: number;
    /**
     * Total siblings under the same parent.
     */
    setSize: number;
    /**
     * Key of the parent node, or null for root-level nodes.
     */
    parentKey: string | null;
    /**
     * Whether this node is expanded.
     */
    expanded: boolean;
    /**
     * Whether this node has no children (or `leaf === true` on the data).
     */
    leaf: boolean;
    /**
     * Whether the node is currently loading (lazy fetch in progress).
     */
    loading: boolean;
    /**
     * Whether the node is selected (single/multiple mode) or fully checked (checkbox mode).
     */
    selected: boolean;
    /**
     * Whether the node is partially checked (checkbox mode only).
     */
    partiallySelected: boolean;
    /**
     * Whether the node is disabled (`disabled === true` on the data).
     */
    disabled: boolean;
}
/**
 * Defines passthrough(pt) options type in TreeNodes component.
 */
export type TreeNodesPassThroughType<E> = PassThroughType<TreeNodesInstance, E>;
/**
 * Defines passthrough(pt) options of TreeNodes component.
 */
export interface TreeNodesPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TreeNodesPassThroughType<React.HTMLAttributes<HTMLUListElement>>;
}
/**
 * Defines valid properties in TreeNodes component.
 */
export interface TreeNodesProps extends BaseComponentProps<TreeNodesInstance, unknown, TreeNodesPassThrough> {
    /**
     * Render-prop invoked once per visible node. Receives a `TreeNodeRow` payload
     * carrying the node data plus its position and state in the tree.
     */
    children?: ((row: TreeNodeRow) => React.ReactNode) | React.ReactNode;
}
/**
 * Defines valid state in TreeNodes component.
 */
export interface TreeNodesState {
}
/**
 * Defines the methods and properties exposed by TreeNodes component.
 */
export interface TreeNodesExposes {
    /**
     * The Tree component instance.
     */
    tree: TreeRootInstance | undefined | null;
}
/**
 * Instance of TreeNodes component.
 */
export type TreeNodesInstance = ComponentInstance<TreeNodesProps, TreeNodesState, TreeNodesExposes>;
